-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.67.3',
  '2026-08-04',
  'Фон: режим «Вписать», честный масштаб, конец дёрганья и сворачиваемые блоки',
  E'Появился режим «Вписать»: картинка помещается целиком, ничего не обрезается и не увеличивается. У «Заполнить» широкая картинка на узком экране раздувается в разы — это и выглядело как «растянуло».\n\nМасштаб в режимах «По центру» и «Замостить» теперь считается от размера самой картинки: 150% — это в полтора раза больше оригинала, а не полтора экрана.\n\nФон больше не дёргается при сворачивании и разворачивании блоков. У точки фокуса подписано, какая ось реально двигает картинку (по второй её просто некуда сдвигать), и бесполезный в данный момент ползунок отключается. У полоски затемнения подписаны концы шкалы — «темнее / как есть / светлее» — и появился сброс: она двусторонняя, середина означает «как есть».\n\nБлок «Фон приложения» и группа «Без папки» теперь сворачиваются. Окно «Переместить картинку» перестало болтаться при прокрутке и умеет сразу создать новую папку.',
  E'Разбор жалоб.\n\n1) «Растягивается в режиме заполнить» — на деле cover не растягивает, а сильно увеличивает и обрезает: картинка 1600x400 на экране 2545x1299 масштабируется в 3.25 раза. Добавлен режим contain («Вписать»); ограничение CHECK на user_settings.bg_position заведено ещё в 0005 из трёх значений, поэтому расширено миграцией 0082 — без неё сохранение падало с 500 на уровне БД.\n\n2) «Фокус по вертикали ничего не меняет» — так работает cover: двигать можно только ту ось, по которой картинка вылезает за экран. Ось теперь вычисляется из соотношений сторон картинки и экрана, вторая блокируется с пояснением.\n\n3) «При масштабе больше 100% дичь» — background-size в процентах считается от КОНТЕЙНЕРА: 150% превращали 1600px в 3817px. Теперь размер считается в пикселях от натурального (нужные размеры берутся из Image() с кэшем). Отложенный колбэк размеров сверяется с текущими url и режимом, иначе он перетирал cover/contain.\n\n4) «Фон скачет при сворачивании блока» — слой inset:0 менял ширину вместе с появлением полосы прокрутки (2545 против 2560), из-за чего cover пересчитывался. Слою задана ширина 100vw.\n\n5) «Окно переноса болтается» — у карточек есть backdrop-filter, а он создаёт содержащий блок для position: fixed, и модалка позиционировалась относительно карточки. Модалки вынесены в body через Teleport; заодно добавлено поле «Новая папка» прямо в окне.\n\n6) Сворачиваемые «Фон приложения» и «Без папки» (состояние в localStorage — это предпочтение устройства), подписи концов у ползунка затемнения и кнопка сброса.\n\nПопутно: сохранённое размещение фона теперь применяется при старте приложения (раньше — только после движения ползунка).\n\nПроверено в браузере: четыре режима дают cover / contain / 2400px / 2400px+repeat для картинки шириной 1600px при масштабе 150%, ширина слоя не зависит от полосы прокрутки, модалка в body с fixed от (0,0), создание папки из окна переноса работает.'
);
-- +goose StatementEnd

